sub:assertion {
  <https://w3id.org/delphi/resource/claim/real-organisms-score-plausible-is-near-worthless> a delphi:Claim ;
    rdfs:label "That real held-out organisms score plausible says almost nothing about whether the design scorer works, because negatives also score plausible." ;
    dct:description "STATUS: a descriptive observation from one blind, family-out held-out evaluation of every scorer version (SCORER-EVALUATION.md lines 14, 45-47); it is not a replicated or independently reviewed result. Across versions, 98 to 99.6 % of real held-out organisms score at or above the 0.5 cut, but only 12 to 17 % of negatives score below it, so each version comes close to calling everything plausible. WHAT IT DOES NOT ESTABLISH: it does not show that any scorer version is useless or wrong, and it does not measure how well a scorer ranks or separates real from negative items at other cuts or by other metrics. It only shows that the share of real organisms scoring high cannot, alone, count as evidence that a scorer works. Per-family low scorers (line 183) and the single gulper eel example (line 186) are illustrations and do not generalise to all families." ;
    delphi:hasEvidence <https://w3id.org/delphi/resource/evidence/real-organisms-score-plausible-is-near-worthless> .

  <https://w3id.org/delphi/resource/evidence/real-organisms-score-plausible-is-near-worthless> a delphi:EvidenceItem ;
    rdfs:label "Held-out plausibility scores: real organisms nearly all pass the 0.5 cut, but most negatives pass it too." ;
    dct:description "Numbers reported from SCORER-EVALUATION.md: the 168 held-out families come from line 14; the real-organism pass rate (lines 45) and the negative rejection rate (line 46) give the contrast; line 47 states the conclusion; lines 183 and 186 give the weak families and the gulper eel example." ;
    schema:additionalProperty
      [ a schema:PropertyValue ; schema:propertyID "heldOutFamilies" ; schema:value 168 ; schema:description "Held-out families scored family-out in the blind run of every scorer version (SCORER-EVALUATION.md:14)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "realPassRatePercentLow" ; schema:value 98 ; schema:description "Lowest share, in percent, of real held-out organisms scoring at or above the 0.5 cut in any version (SCORER-EVALUATION.md:45)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "realPassRatePercentHigh" ; schema:value 99.6 ; schema:description "Highest share, in percent, of real held-out organisms scoring at or above the 0.5 cut in any version (SCORER-EVALUATION.md:45)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "plausibilityCut" ; schema:value 0.5 ; schema:description "Plausibility cut used for both real organisms and negatives (SCORER-EVALUATION.md:45-46)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "negativesBelowCutPercentLow" ; schema:value 12 ; schema:description "Lowest share, in percent, of negatives scoring below the 0.5 cut (SCORER-EVALUATION.md:46)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "negativesBelowCutPercentHigh" ; schema:value 17 ; schema:description "Highest share, in percent, of negatives scoring below the 0.5 cut (SCORER-EVALUATION.md:46)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "minRealItemsPerFlaggedFamily" ; schema:value 3 ; schema:description "Minimum real items per family for the under-80-percent check (SCORER-EVALUATION.md:183)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "familyPlausibleThresholdPercent" ; schema:value 80 ; schema:description "Share of real items scoring plausible below which a family is flagged (SCORER-EVALUATION.md:183)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "eurypharyngidaeScoringPlausible" ; schema:value 3 ; schema:description "Eurypharyngidae (gulper eels): 3 of 5 real items score plausible (SCORER-EVALUATION.md:183)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "eurypharyngidaeTotal" ; schema:value 5 ; schema:description "Eurypharyngidae real items in total (SCORER-EVALUATION.md:183)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "aspredinidaeScoringPlausible" ; schema:value 20 ; schema:description "Aspredinidae (banjo catfishes): 20 of 29 real items score plausible (SCORER-EVALUATION.md:183)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "aspredinidaeTotal" ; schema:value 29 ; schema:description "Aspredinidae real items in total (SCORER-EVALUATION.md:183)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "gulperEelScore" ; schema:value 0.15 ; schema:description "Plausibility score of fs-05942, a gulper eel (SCORER-EVALUATION.md:186)." ] ,
      [ a schema:PropertyValue ; schema:propertyID "gulperEelNearestNeighbourDistance" ; schema:value 0.96 ; schema:description "Distance from fs-05942 to its nearest remaining neighbour, the cutlassfish Lepturacanthus savala, once its family is removed (SCORER-EVALUATION.md:186)." ] .
}

